//! Parity and regression tests for the chatterbox (T3 + S3Gen) family.
//!
//! Pinned fixtures reside in `testdata/tts_chatterbox/`, generated by
//! `tools/gen_chatterbox_fixtures.py` against mlx-audio commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3) on the CPU
//! device. The generator runs the true reference modules at tiny seeded
//! geometry (a 2-layer llama-32 backbone rides the reference
//! `LLAMA_CONFIGS` entry; the perceiver, flow, HiFT, CAMPPlus, voice
//! encoder, and S3 tokenizer all run reference code at shrunk widths),
//! so the traces carry the conditioning rows, the greedy and sampled T3
//! streams with per-step head logits, the flow mel, the HiFT waveform
//! with recorded sine draws, the end-to-end generate realization, the
//! conditioning path through the tiny S3 tokenizer, and the sampler
//! math on fixed logits.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::{
    drop_invalid_tokens, punc_norm, Conditionals, GenCond, GenerateParams, Model, ModelConfig,
    T3Cond, T3GenParams, SPEECH_VOCAB_SIZE,
};
use crate::music::minimax_music3::rng;
use crate::tts::sampling;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_chatterbox")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Reads a float vector where non-finite entries carry `null` (JSON has
/// no infinity); `null` maps back to -inf.
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().map(|x| x as f32).unwrap_or(f32::NEG_INFINITY))
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

/// Reads a float32 `.npy` into (shape, data).
fn read_npy(path: &Path) -> (Vec<usize>, Vec<f32>) {
    let bytes = std::fs::read(path).expect("npy file");
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

/// Reads an int32 `.npy` into (shape, data).
fn read_npy_i32(path: &Path) -> (Vec<usize>, Vec<i32>) {
    let bytes = std::fs::read(path).expect("npy file");
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

fn max_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Opens the tiny fixture model with its S3 tokenizer.
fn open_model() -> Model {
    Model::open(&testdata("")).expect("opens the fixture model")
}

/// The fixture T3 conditioning (`t3/traces.json`).
fn t3_cond_from_traces(traces: &Value) -> T3Cond {
    T3Cond {
        speaker_emb: f32_vec(&traces["speaker_emb"]),
        cond_prompt_speech_tokens: Some(i32_vec(&traces["cond_prompt_speech_tokens"])),
        emotion_adv: traces["emotion_adv"].as_f64().unwrap() as f32,
    }
}

fn fixture_t3_params() -> T3GenParams {
    T3GenParams {
        max_new_tokens: 10,
        temperature: 0.0,
        top_p: 1.0,
        min_p: 0.05,
        repetition_penalty: 1.2,
        cfg_weight: 0.5,
    }
}

/// The flow-case reference inputs.
struct FlowInputs {
    prompt_tokens: Vec<i32>,
    gen_tokens: Vec<i32>,
    prompt_feat: Vec<f32>,
    embedding: Vec<f32>,
    flow_mel: Vec<f32>,
}

fn flow_inputs() -> FlowInputs {
    let (_, prompt_tokens) = read_npy_i32(&testdata("flow/prompt_tokens.npy"));
    let (_, gen_tokens) = read_npy_i32(&testdata("flow/gen_tokens.npy"));
    let (_, prompt_feat) = read_npy(&testdata("flow/prompt_feat.npy"));
    let (_, embedding) = read_npy(&testdata("flow/embedding.npy"));
    let (_, flow_mel) = read_npy(&testdata("flow/flow_mel.npy"));
    FlowInputs {
        prompt_tokens,
        gen_tokens,
        prompt_feat,
        embedding,
        flow_mel,
    }
}

fn flow_gen_cond(inputs: &FlowInputs) -> GenCond {
    GenCond {
        prompt_token: inputs.prompt_tokens.clone(),
        prompt_feat: inputs.prompt_feat.clone(),
        embedding: inputs.embedding.clone(),
    }
}

#[test]
fn config_matches_reference_defaults() {
    let value = read_json(&testdata("config.json"));
    let config = ModelConfig::from_json(&value).unwrap();
    // T3 specials are the pinned reference tokens.
    assert_eq!(config.t3.start_text_token, 255);
    assert_eq!(config.t3.stop_text_token, 0);
    assert_eq!(config.t3.start_speech_token, 6561);
    assert_eq!(config.t3.stop_speech_token, 6562);
    assert_eq!(config.t3.speech_tokens_dict_size, 8194);
    assert_eq!(config.t3.text_tokens_dict_size, 704);
    assert_eq!(config.t3.speech_cond_prompt_len, 150);
    assert_eq!(config.t3.speaker_embed_size, 256);
    assert_eq!(config.t3.input_pos_emb, "learned");
    assert_eq!(config.text_preprocessing, "legacy");
    assert_eq!(config.s3_sr, 16000);
    assert_eq!(config.s3gen_sr, 24000);
    assert_eq!(config.enc_cond_len, 6 * 16000);
    assert_eq!(config.dec_cond_len, 10 * 24000);
    // Flow defaults survive parsing: the fixture overrides a subset.
    let defaults = ModelConfig::default();
    assert_eq!(
        config.flow.inference_cfg_rate,
        defaults.flow.inference_cfg_rate
    );
    assert_eq!(config.flow.output_size, 80);
    assert_eq!(config.flow.upsample_stride, 2);
    assert_eq!(config.hift.base_channels, 64);
    // The multilingual-only config path widens the text table.
    let multilingual =
        ModelConfig::from_json(&serde_json::json!({ "multilingual": true })).unwrap();
    assert_eq!(multilingual.t3.text_tokens_dict_size, 2454);
    let english = ModelConfig::from_json(&serde_json::json!({})).unwrap();
    assert_eq!(english.t3.text_tokens_dict_size, 704);
}

#[test]
fn conditioning_rows_match_reference() {
    let traces = read_json(&testdata("t3/traces.json"));
    let mut model = open_model();
    let cond = t3_cond_from_traces(&traces);
    let cond_rows = model.t3.prepare_conditioning(&cond).unwrap();
    let expected = f32_vec(&traces["cond_rows"]);
    let diff = max_diff(&cond_rows, &expected);
    assert!(diff < 2e-4, "conditioning rows difference {diff}");
}

#[test]
fn t3_greedy_generation_matches_reference() {
    let traces = read_json(&testdata("t3/traces.json"));
    let mut model = open_model();
    let cond = t3_cond_from_traces(&traces);
    let text_ids = i32_vec(&traces["text_ids"]);
    let prompt = model.prepare_text_tokens(&text_ids);
    let mut keys = rng::KeySequence::new(0);
    let (ids, stopped) = model
        .t3
        .inference(&cond, &prompt, &fixture_t3_params(), &mut keys)
        .unwrap();
    assert_eq!(stopped, super::t3::StopReason::MaxTokens);
    let expected = i32_vec(&traces["greedy_ids"]);
    assert_eq!(ids, expected, "greedy id stream diverged");

    // The per-step decision inputs: CFG combine + repetition penalty
    // over the recorded head calls; the per-step argmax must reproduce
    // the chosen ids and the recorded decision margins.
    let (_, head_calls) = read_npy(&testdata("t3/greedy_head_calls.npy"));
    let steps = expected.len() - 1;
    let vocab = head_calls.len() / (steps * 2);
    assert_eq!(vocab, model.config.t3.speech_tokens_dict_size);
    let mut margins = Vec::with_capacity(steps);
    let mut generated: Vec<i32> = vec![expected[0]];
    for step in 0..steps {
        let cond_row = &head_calls[step * 2 * vocab..(step * 2 + 1) * vocab];
        let uncond_row = &head_calls[(step * 2 + 1) * vocab..(step + 2) * vocab];
        let mut logits: Vec<f32> = cond_row
            .iter()
            .zip(uncond_row)
            .map(|(&c, &u)| c + 0.5 * (c - u))
            .collect();
        sampling::apply_repetition_penalty(&mut logits, &generated, 1.2, 10).unwrap();
        let mut sorted = logits.clone();
        sorted.sort_by(|a, b| b.partial_cmp(a).unwrap());
        margins.push(sorted[0] - sorted[1]);
        let chosen = expected[1 + step];
        assert_eq!(
            sampling::argmax(&logits) as i32,
            chosen,
            "step {step} argmax diverged"
        );
        generated.push(chosen);
    }
    let recorded = f32_vec(&traces["greedy_margins"]);
    for (a, b) in margins.iter().zip(&recorded) {
        assert!((a - b).abs() < 2e-4, "margin {a} vs {b}");
        assert!(*a > 0.01, "thin greedy margin {a}");
    }
}

#[test]
fn t3_sampled_generation_replays_the_recorded_stream() {
    let traces = read_json(&testdata("t3/traces.json"));
    let mut model = open_model();
    let cond = t3_cond_from_traces(&traces);
    let text_ids = i32_vec(&traces["text_ids"]);
    let prompt = model.prepare_text_tokens(&text_ids);
    let seed = traces["sampled_seed"].as_u64().unwrap();
    let params = T3GenParams {
        max_new_tokens: 10,
        temperature: traces["temperature"].as_f64().unwrap() as f32,
        top_p: traces["top_p"].as_f64().unwrap() as f32,
        min_p: traces["min_p"].as_f64().unwrap() as f32,
        repetition_penalty: traces["repetition_penalty"].as_f64().unwrap() as f32,
        cfg_weight: traces["cfg_weight"].as_f64().unwrap() as f32,
    };
    let mut keys = rng::KeySequence::new(seed);
    let (ids, _) = model
        .t3
        .inference(&cond, &prompt, &params, &mut keys)
        .unwrap();
    let expected = i32_vec(&traces["sampled_ids"]);
    assert_eq!(ids, expected, "sampled id stream diverged");
    // The crate RNG is the MLX-compatible threefry stream: a fresh
    // sequence with the same seed redraws the same ids.
    let mut keys = rng::KeySequence::new(seed);
    let (ids_b, _) = model
        .t3
        .inference(&cond, &prompt, &params, &mut keys)
        .unwrap();
    assert_eq!(ids_b, expected, "sampled replay diverged");
}

#[test]
fn flow_mel_matches_reference() {
    let mut model = open_model();
    let inputs = flow_inputs();
    let mel = model
        .flow
        .infer(
            &inputs.gen_tokens,
            &inputs.prompt_tokens,
            &inputs.prompt_feat,
            &inputs.embedding,
            10,
        )
        .unwrap();
    let diff = max_diff(&mel, &inputs.flow_mel);
    assert!(diff < 2e-4, "flow mel difference {diff}");
}

#[test]
fn hift_waveform_matches_reference() {
    let traces = read_json(&testdata("hift/traces.json"));
    let model = open_model();
    let inputs = flow_inputs();
    let (_, phase) = read_npy(&testdata("hift/phase.npy"));
    let (_, sine_noise) = read_npy(&testdata("hift/sine_noise.npy"));
    let (_, f0_expected) = read_npy(&testdata("hift/f0.npy"));

    let f0 = model.hift.predict_f0(&inputs.flow_mel).unwrap();
    let diff = max_diff(&f0, &f0_expected);
    assert!(diff < 2e-3, "f0 difference {diff}");

    let draws = super::hift::SineDraws {
        phase,
        noise: sine_noise,
    };
    let wav = model.hift.infer(&inputs.flow_mel, Some(&draws)).unwrap();
    let (_, wav_expected) = read_npy(&testdata("hift/wav.npy"));
    assert_eq!(wav.len(), traces["wav_len"].as_u64().unwrap() as usize);
    let diff = max_diff(&wav, &wav_expected);
    assert!(diff < 2e-4, "hift waveform difference {diff}");
    // The deterministic zero-draw path is a different signal (the sine
    // bed is voiced here), which pins the recorded draws as load
    // bearing.
    let wav_zero = model.hift.infer(&inputs.flow_mel, None).unwrap();
    assert!(max_diff(&wav_zero, &wav_expected) > 1e-3);
}

#[test]
fn end_to_end_generate_matches_reference() {
    let t3_traces = read_json(&testdata("t3/traces.json"));
    let e2e_traces = read_json(&testdata("end_to_end/traces.json"));
    let mut model = open_model();
    let inputs = flow_inputs();
    let conds = Conditionals {
        t3: t3_cond_from_traces(&t3_traces),
        gen: flow_gen_cond(&inputs),
    };
    let (_, sine_noise) = read_npy(&testdata("end_to_end/sine_noise.npy"));
    let draws = super::hift::SineDraws {
        phase: f32_vec(&e2e_traces["phase"]),
        noise: sine_noise,
    };
    let text_ids = i32_vec(&e2e_traces["text_ids"]);
    let params = GenerateParams {
        t3: fixture_t3_params(),
        ..GenerateParams::default()
    };
    let generated = model
        .generate(&text_ids, &conds, &params, Some(&draws))
        .unwrap();
    assert_eq!(
        generated.ids,
        i32_vec(&e2e_traces["ids"]),
        "end-to-end id stream diverged"
    );
    assert_eq!(
        generated.speech_tokens,
        i32_vec(&e2e_traces["speech_tokens"]),
        "speech token crop diverged"
    );
    let (_, wav_expected) = read_npy(&testdata("end_to_end/wav.npy"));
    assert_eq!(generated.samples.len(), wav_expected.len());
    let diff = max_diff(&generated.samples, &wav_expected);
    assert!(diff < 2e-4, "end-to-end waveform difference {diff}");
    assert_eq!(generated.sample_rate, 24000);
}

#[test]
fn campplus_embedding_matches_reference() {
    let traces = read_json(&testdata("campplus/traces.json"));
    let model = open_model();
    let (_, wave) = read_npy(&testdata("campplus/wave.npy"));
    let (_, fbank_expected) = read_npy(&testdata("campplus/fbank.npy"));
    let (_, embedding_expected) = read_npy(&testdata("campplus/embedding.npy"));

    let fbank_rows = super::campplus::kaldi_fbank(&wave).unwrap();
    let frames = fbank_rows.len();
    let feat_dim = fbank_rows[0].len();
    assert_eq!(
        [frames, feat_dim],
        [
            traces["fbank_shape"][0].as_u64().unwrap() as usize,
            traces["fbank_shape"][1].as_u64().unwrap() as usize
        ]
    );
    let mut fbank = Vec::with_capacity(frames * feat_dim);
    for row in &fbank_rows {
        fbank.extend_from_slice(row);
    }
    let diff = max_diff(&fbank, &fbank_expected);
    assert!(diff < 2e-4, "kaldi fbank difference {diff}");

    // Per-feature mean removal over frames, then the embedding.
    for c in 0..feat_dim {
        let mean = (0..frames).map(|f| fbank[f * feat_dim + c]).sum::<f32>() / frames as f32;
        for f in 0..frames {
            fbank[f * feat_dim + c] -= mean;
        }
    }
    let embedding = model.campplus.inference(&fbank, frames);
    let diff = max_diff(&embedding, &embedding_expected);
    assert!(diff < 2e-4, "campplus embedding difference {diff}");
}

#[test]
fn voice_encoder_embedding_matches_reference() {
    let model = open_model();
    let (_, wave) = read_npy(&testdata("voice_encoder/wave.npy"));
    let (_, expected) = read_npy(&testdata("voice_encoder/speaker_emb.npy"));
    let speaker = model.ve.embeds_from_wav(&wave, Some(20.0)).unwrap();
    let diff = max_diff(&speaker, &expected);
    assert!(diff < 2e-4, "voice encoder embedding difference {diff}");
    // The result is L2-normalized.
    let norm: f32 = speaker.iter().map(|v| v * v).sum::<f32>().sqrt();
    assert!((norm - 1.0).abs() < 1e-4, "speaker norm {norm}");
}

#[test]
fn conditioning_path_matches_reference() {
    let traces = read_json(&testdata("conditioning/traces.json"));
    let mut model = open_model();
    let (_, wav_16k_full) = read_npy(&testdata("conditioning/wav_16k_full.npy"));
    let (_, wav_24k) = read_npy(&testdata("conditioning/wav_24k.npy"));
    let (_, wav_16k_from_24k) = read_npy(&testdata("conditioning/wav_16k_from_24k.npy"));
    let (_, feat_expected) = read_npy(&testdata("conditioning/prompt_feat.npy"));
    let (_, tokens_expected) = read_npy_i32(&testdata("conditioning/prompt_token.npy"));
    let (_, embedding_expected) = read_npy(&testdata("conditioning/embedding.npy"));
    let (_, speaker_expected) = read_npy(&testdata("conditioning/speaker_emb.npy"));

    let conds = model
        .prepare_conditionals(&wav_16k_full, &wav_24k, &wav_16k_from_24k, 0.4)
        .unwrap();
    assert_eq!(
        conds.gen.prompt_token, tokens_expected,
        "S3Gen prompt tokens diverged"
    );
    let diff = max_diff(&conds.gen.prompt_feat, &feat_expected);
    assert!(diff < 2e-4, "prompt mel difference {diff}");
    let diff = max_diff(&conds.gen.embedding, &embedding_expected);
    assert!(diff < 2e-4, "campplus prompt embedding difference {diff}");
    let diff = max_diff(&conds.t3.speaker_emb, &speaker_expected);
    assert!(
        diff < 2e-4,
        "voice encoder speaker embedding difference {diff}"
    );
    assert_eq!(
        conds.t3.cond_prompt_speech_tokens.unwrap(),
        i32_vec(&traces["t3_cond_prompt_tokens"]),
        "T3 prompt tokens diverged"
    );
    assert!((conds.t3.emotion_adv - 0.4).abs() < 1e-6);
}

#[test]
fn sampling_math_matches_reference() {
    let traces = read_json(&testdata("sampling/traces.json"));
    for case in traces["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        match name {
            "cfg_combine" => {
                let cond = f32_vec(&case["cond"]);
                let uncond = f32_vec(&case["uncond"]);
                let weight = case["cfg_weight"].as_f64().unwrap() as f32;
                let combined: Vec<f32> = cond
                    .iter()
                    .zip(&uncond)
                    .map(|(&c, &u)| c + weight * (c - u))
                    .collect();
                let diff = max_diff(&combined, &f32_vec(&case["combined"]));
                assert!(diff < 1e-5, "cfg combine difference {diff}");
            }
            "repetition_penalty_duplicates" => {
                let mut logits = f32_vec(&case["logits"]);
                let context = case["context"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|v| v.as_i64().unwrap() as i32)
                    .collect::<Vec<_>>();
                let penalty = case["penalty"].as_f64().unwrap() as f32;
                sampling::apply_repetition_penalty(&mut logits, &context, penalty, 20).unwrap();
                let diff = max_diff(&logits, &f32_vec(&case["penalized"]));
                assert!(diff < 1e-5, "penalty difference {diff}");
            }
            "top_p_raw_0_9" | "top_p_raw_0_5" => {
                let mut filtered = f32_vec_masked(&case["logits"]);
                sampling::apply_top_p(&mut filtered, case["top_p"].as_f64().unwrap() as f32);
                let diff = max_diff_with_infinite(&filtered, &f32_vec_masked(&case["filtered"]));
                assert!(diff < 1e-5, "{name} difference {diff}");
            }
            "min_p_raw_0_05" | "min_p_raw_0_4" => {
                let mut filtered = f32_vec_masked(&case["logits"]);
                sampling::apply_min_p(&mut filtered, case["min_p"].as_f64().unwrap() as f32, 1)
                    .unwrap();
                let diff = max_diff_with_infinite(&filtered, &f32_vec_masked(&case["filtered"]));
                assert!(diff < 1e-5, "{name} difference {diff}");
            }
            "filtered_categorical" => {
                let logits = f32_vec_masked(&case["logits"]);
                let temperature = case["temperature"].as_f64().unwrap() as f32;
                let uniform = f32_vec(&case["uniform"])[0];
                let winner = categorical_with_uniform(&logits, temperature, uniform);
                assert_eq!(
                    winner,
                    case["winner"].as_u64().unwrap() as usize,
                    "{name} winner diverged"
                );
            }
            "greedy_argmax" => {
                let logits = f32_vec(&case["logits"]);
                assert_eq!(
                    sampling::argmax(&logits),
                    case["argmax"].as_u64().unwrap() as usize,
                    "{name} argmax diverged"
                );
            }
            other => panic!("unknown sampling case {other}"),
        }
    }
}

/// The inverse-CDF categorical draw with a given uniform (the fixture
/// records the reference's draw so the Rust math replays it without
/// consuming the crate RNG).
fn categorical_with_uniform(logits: &[f32], temperature: f32, uniform: f32) -> usize {
    let scale = 1.0 / temperature;
    let max = logits.iter().copied().fold(f32::NEG_INFINITY, f32::max);
    let weights: Vec<f64> = logits
        .iter()
        .map(|&x| ((x - max) * scale) as f64)
        .map(|v| v.exp())
        .collect();
    let total: f64 = weights.iter().sum();
    let u = uniform as f64 * total;
    let mut cumulative = 0.0f64;
    let mut count = 0usize;
    for &w in &weights {
        if cumulative > u {
            break;
        }
        count += 1;
        cumulative += w;
    }
    count.saturating_sub(1).min(weights.len() - 1)
}

/// Max diff that treats -inf == -inf as equal (the filtered vectors).
fn max_diff_with_infinite(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(a.len(), b.len());
    let mut worst = 0.0f32;
    for (x, y) in a.iter().zip(b) {
        if x.is_infinite() && y.is_infinite() {
            continue;
        }
        worst = worst.max((x - y).abs());
    }
    worst
}

#[test]
fn token_crop_and_text_normalization_match_reference() {
    // drop_invalid_tokens: crop between the first start and stop
    // markers; the generate path then filters >= 6561 keeping order.
    let ids = [6561, 5, 7000, 6, 6562, 7, 6561, 8];
    assert_eq!(drop_invalid_tokens(&ids), vec![5, 7000, 6]);
    let filtered: Vec<i32> = drop_invalid_tokens(&ids)
        .into_iter()
        .filter(|&t| t < SPEECH_VOCAB_SIZE)
        .collect();
    assert_eq!(filtered, vec![5, 6]);
    // No markers at all keeps everything.
    assert_eq!(drop_invalid_tokens(&[1, 2, 3]), vec![1, 2, 3]);
    // Stop before start: empty crop.
    assert!(drop_invalid_tokens(&[6562, 6561, 5]).is_empty());

    // punc_norm: capitalization, whitespace collapse, punctuation
    // replacement, and the appended full stop.
    assert_eq!(
        punc_norm("hello   world -  friend", true),
        "Hello world, friend."
    );
    assert_eq!(punc_norm("it is fine!", true), "It is fine!");
    assert_eq!(punc_norm("\u{201c}quoted\u{201d}", false), "\"quoted\".");
    // "..." becomes ", " and the trailing comma suppresses the stop.
    assert_eq!(punc_norm("trailing dots...", true), "Trailing dots,");
    assert_eq!(
        punc_norm("", true),
        "You need to add some text for me to talk."
    );
    // The v3 fullcase convention does not capitalize.
    assert_eq!(punc_norm("lower start", false), "lower start.");
    // Sentence enders suppress the appended stop.
    assert_eq!(punc_norm("already ends?", true), "Already ends?");
}

#[test]
#[ignore = "requires a real chatterbox checkpoint in TURBOSPARK_CHATTERBOX_MODEL_DIR"]
fn real_checkpoint_gate() {
    let dir = match std::env::var("TURBOSPARK_CHATTERBOX_MODEL_DIR") {
        Ok(dir) => PathBuf::from(dir),
        Err(_) => return,
    };
    let config_value = crate::quant::read_json(&dir.join("config.json")).unwrap();
    let config = ModelConfig::from_json(&config_value).unwrap();
    let path = dir.join("model.safetensors");
    let model = Model::load(&path, &config).expect("loads the real checkpoint");
    assert_eq!(model.config.t3.speech_tokens_dict_size, 8194);
    assert_eq!(model.config.flow.vocab_size, 6561);
    assert_eq!(model.config.flow.output_size, 80);
    assert_eq!(model.config.hift.base_channels, 512);
    assert_eq!(model.config.campplus.embedding_size, 192);
    assert_eq!(model.config.ve.speaker_embed_size, 256);
    // The reference S3 tokenizer loads next to it when installed.
    if let Ok(s3_dir) = std::env::var("TURBOSPARK_S3_MODEL_DIR") {
        let model = model.with_s3_tokenizer(Path::new(&s3_dir)).unwrap();
        assert!(model.s3_tokenizer.is_some());
    }
}
